])

def debug_transform(g):
    h = len(g)
    sep_row = None
    for i in range(h):
        if all(g[i][j] == 2 for j in range(len(g[0]))):
            sep_row = i
            break

    if sep_row is None:
        return g

    top_row = None
    top_pixel = None
    for i in range(sep_row):
        for j in range(len(g[0])):
            if g[i][j] != 0 and g[i][j] != 2:
                top_row = i
                top_pixel = g[i][j]
                break
        if top_row:
            break

    bottom_row = None
    bottom_pixel = None
    for i in range(sep_row, h):
        for j in range(len(g[0])):
            if g[i][j] != 0 and g[i][j] != 2:
                bottom_row = i
                bottom_pixel = g[i][j]
                break
        if bottom_row:
            break

    print(f"sep_row={sep_row}, top_row={top_row}, top_pixel={top_pixel}")
    print(f"bottom_row={bottom_row}, bottom_pixel={bottom_pixel}")

    if not top_row or not bottom_row or top_pixel != bottom_pixel:
        return g

    overlap_cols = set()
    for c in range(len(g[0])):
        if g[top_row][c] == top_pixel and g[bottom_row][c] == bottom_pixel:
            overlap_cols.add(c)

    print(f"overlap_cols = {overlap_cols}")

    result = [row[:] for row in g]
    for c in overlap_cols:
        for r in range(top_row + 1, sep_row):
            print(f"Setting row {r}, col {c} to 4")
            result[r][c] = 4

    return result

result = debug_transform(grid)
print("\nResult:")
for row in result:
    print(row)

